ï»¿<style>
.print-format { font-family: Lato, Arial, sans-serif; color: #102136; font-size: 11pt; padding: 20mm; }
.dd-brand { color: #102136 !important; font-size: 30pt; font-weight: 700; margin: 0 0 8mm; border-bottom: 1px solid #00877f; padding-bottom: 4mm; }
.dd-brand span { color: #00877f; }
.dd-caption { color: #64748b; font-size: 9pt; text-transform: uppercase; letter-spacing: .6px; }
.dd-reference { font-size: 16pt; font-weight: 700; }
.dd-panel { background: #eef8f7; padding: 6mm; margin: 8mm 0; border-radius: 2mm; }
.dd-panel table { width: 100%; }
.dd-panel td { width: 50%; vertical-align: top; }
.dd-panel td + td { border-left: 1px solid #dce4e8; padding-left: 6mm; }
.dd-heading { font-size: 20pt; font-weight: 700; margin: 8mm 0 3mm; }
.dd-items { width: 100%; border-collapse: collapse; }
.dd-items th { color: #64748b; font-size: 9pt; padding: 3mm 2mm; border-bottom: 1px solid #00877f; }
.dd-items td { padding: 5mm 2mm; border-bottom: 1px solid #dce4e8; vertical-align: top; }
.dd-items tr { page-break-inside: avoid; }
.dd-number { color: #00877f; font-weight: 700; }
.dd-money { text-align: right; white-space: nowrap; }
.dd-total { text-align: right; font-size: 16pt; font-weight: 700; color: #00877f; margin: 6mm 0; }
.dd-notes { white-space: pre-wrap; }
</style>
<div class="dd-brand">Diaspora <span>Desk</span></div>
<table style="width:100%"><tr><td><div class="dd-caption">Quotation reference</div><div class="dd-reference">{{ doc.name | e }}</div></td><td style="text-align:right"><div class="dd-caption">Request reference</div><strong>{{ doc.request | e }}</strong><br>{{ doc.status | e }}</td></tr></table>
<div class="dd-panel"><table><tr><td><div class="dd-caption">Prepared for</div><strong>{{ doc.customer_name | e }}</strong><br>{{ doc.customer_email | e }}</td><td><div class="dd-caption">Quotation date</div><strong>{{ frappe.utils.formatdate(doc.quotation_date) }}</strong><br><span class="dd-caption">Valid until</span><br>{{ frappe.utils.formatdate(doc.valid_until) }}</td></tr></table></div>
<h2 class="dd-heading">Your quotation</h2>
<p>Proposed scope and pricing for your requested project checks. Planned scout numbers form part of this quotation. Current assignments are shown separately in your customer account after your deposit is verified.</p>
<table class="dd-items"><thead><tr><th style="width:9%">Project</th><th>Scope</th><th class="dd-money">Scouts planned</th><th class="dd-money">Quantity</th><th class="dd-money">Rate ({{ doc.currency | e }})</th><th class="dd-money">Amount</th></tr></thead><tbody>
{% for item in doc.items %}{% set assignments = frappe.get_all("Field Task", filters={"field_request": item.field_request, "status": ["!=", "Cancelled"]}, fields=["scout_profile"]) %}<tr><td class="dd-number">{{ "%02d" | format(loop.index) }}</td><td><strong>{{ item.project_title | e }}</strong>{% if item.description != item.project_title %}<div class="dd-notes">{{ item.description | e }}</div>{% endif %}<div class="dd-caption">Currently assigned: {{ assignments | map(attribute="scout_profile") | unique | list | length }} scouts at time of printing</div></td><td class="dd-money">{{ item.get("planned_scouts") or "To confirm" }}</td><td class="dd-money">{{ item.quantity }}</td><td class="dd-money">{{ "{:,.2f}".format(item.rate) }}</td><td class="dd-money">{{ "{:,.2f}".format(item.amount) }}</td></tr>{% endfor %}
</tbody></table>
<div class="dd-total">Total {{ doc.currency | e }} {{ "{:,.2f}".format(doc.total) }}</div>
{% if doc.get("deposit_amount") %}<p><strong>50% deposit:</strong> {{ doc.currency | e }} {{ "{:,.2f}".format(doc.deposit_amount) }}<br><strong>50% balance on completion:</strong> {{ doc.currency | e }} {{ "{:,.2f}".format(doc.balance_amount) }}</p><p>Accept this quotation and pay the deposit through your customer account. Scouts are assigned after the deposit is verified. Both payments are linked to this quotation.</p>{% endif %}{% if doc.agreed_completion_date %}<div class="dd-panel"><div class="dd-caption">Proposed completion date</div><strong>{{ frappe.utils.formatdate(doc.agreed_completion_date) }}</strong></div>{% endif %}
{% if doc.terms %}<h3>Terms and payment arrangements</h3><div class="dd-notes">{{ doc.terms | e }}</div>{% endif %}
